<script lang="ts">
    import MotionContainer from './_MotionContainer.svelte'
    import type { HTMLElementProps } from '../types'
    import { isMotionValueChild } from '../utils/motionValueChild'

    let { children, ref = $bindable(), ...rest }: HTMLElementProps = $props()
    const motionValueChild = $derived(isMotionValueChild(children) ? children : undefined)
    const childSnippet = $derived(typeof children === 'function' ? children : undefined)
</script>

<MotionContainer bind:ref tag="b" {motionValueChild} {...rest}>
    {@render childSnippet?.()}
</MotionContainer>
